          "Canalis femoralis": "Femoral kanal inguinal ligamanın altında, femoral ven medialinde yer alır ve femoral fıtıklarla ilişkilidir. Bu vakada şişlik inguinal ligamanın üzerinde ve epigastrik damarların medialinde izlenmiştir.",
