    "coreKnowledge": "Peritoneal bağ sorularında bağın yalnızca sınırını değil, içinde taşıdığı damar, kanal ve komşuluk paketini birlikte düşünmek gerekir.",
    "examPearl": "Karaciğer kanamasında küçük omentum serbest kenarının kompresyonu, portal triad içeriğini hedeflediği için peritoneal bağ anatomisiyle düşünülmelidir.",
    "whyCorrect": "Karaciğer hilusuna giden ana damar-safra yolu paketi küçük omentumun serbest kenarında yer alan peritoneal bağ içinde seyreder. Bu düzeyin kompresyonuyla hepatik giriş akımının azalması, karaciğer çevresi kanamanın geçici olarak kontrol edilmesini açıklar; mide, kolon veya dalak ilişkili bağlar aynı etkiyi beklenen şekilde oluşturmaz.",
    "optionComparison": {
      "Ligamentum hepatogastricum": "Bu bağ küçük omentumun bir parçasıdır ve mide küçük kurvaturası ile karaciğer arasında uzanır; üst karın cerrahisinde yakın görünür. Ancak portal triadın ana kompresyon düzeyi serbest kenar değildir; bu nedenle kanamanın belirgin azalmasını en iyi açıklamaz.",
      "Ligamentum hepatoduodenale": "Doğru yanıttır; küçük omentumun serbest kenarında portal ven, hepatik arter ve safra yolu paketi birlikte seyreder. Karaciğer hilusuna yönelen bu paketin kompresyonu, giriş akımını azaltarak travmatik karaciğer kanamasında geçici kontrol sağlayabilir.",
      "Ligamentum falciforme hepatis": "Bu bağ karaciğeri ön karın duvarına bağlar ve ligamentum teres hepatis ile ilişkili olduğu için yüzeyel karaciğer anatomisinde önemlidir. Ancak portal triad içeriğini taşımaz; serbest kenar kompresyonuyla kanama azalmasını açıklamaz.",
      "Ligamentum gastrocolicum": "Bu bağ mide büyük kurvaturası ile transvers kolon arasında uzanır ve omental bursa girişimlerinde karşımıza çıkar. Karaciğer hilusuna giden damar-safra yolu paketini içermez; bu vakadaki kompresyon yanıtı ile uyumlu değildir.",
      "Ligamentum phrenicocolicum": "Bu bağ kolon fleksurası ve diyafram komşuluğuyla ilişkilidir, dalak alt desteği olarak bilinebilir. Sağ üst kadran karaciğer hilusu kanama kontrolünde hedeflenen portal yapı paketini taşımaz."
    },
