        "Somatostatin aracılı postprandiyal sekresyon yanıtlarının genel baskılanması": "Somatostatin inhibitör bir düzenleyicidir ve ölçülen belirgin sıvı-bikarbonat artışını açıklamaz. Vakada aktif bir nötralizasyon yanıtı vardır."
